#include <cstdint>
#include <utility>
#include <vector>

std::vector<std::pair<std::uint64_t, std::uint64_t>> callTargets(const std::vector<std::uint8_t>& code, std::uint64_t base)
{
    std::vector<std::pair<std::uint64_t, std::uint64_t>> calls;
    std::size_t i{ 0 };
    while (i < code.size())
    {
        if (code[i] != 0xE8) { ++i; continue; }            // padding
        if (i + 5 > code.size()) break;                   // cut off
        const std::uint32_t raw{ static_cast<std::uint32_t>(code[i + 1]) | (static_cast<std::uint32_t>(code[i + 2]) << 8)
                               | (static_cast<std::uint32_t>(code[i + 3]) << 16) | (static_cast<std::uint32_t>(code[i + 4]) << 24) };
        const auto displacement{ static_cast<std::int32_t>(raw) };
        const std::uint64_t at{ base + i };
        calls.push_back({ at, at + 5 + static_cast<std::uint64_t>(static_cast<std::int64_t>(displacement)) });
        i += 5;
    }
    return calls;
}

std::vector<std::uint64_t> callersOf(const std::vector<std::uint8_t>& code, std::uint64_t base, std::uint64_t target)
{
    std::vector<std::uint64_t> callers;
    for (const auto& [at, to] : callTargets(code, base))
        if (to == target) callers.push_back(at);
    return callers;
}

