using C = std::vector<std::pair<std::uint64_t, std::uint64_t>>;
TEST("the example") { CHECK(callTargets({ 0xE8, 0x6B, 0, 0, 0, 0xCC, 0xE8, 0xF0, 0xFF, 0xFF, 0xFF }, 0x140001000ull) == C({ { 0x140001000ull, 0x140001070ull }, { 0x140001006ull, 0x140000FFBull } })); }
TEST("a call to the very next instruction") { CHECK(callTargets({ 0xE8, 0, 0, 0, 0 }, 0x1000) == C({ { 0x1000, 0x1005 } })); }
TEST("callers of one function")
{
    // Three calls at 0x2000, 0x2005, 0x200A; the first and third call 0x3000.
    const std::vector<std::uint8_t> code{ 0xE8, 0xFB, 0x0F, 0, 0, 0xE8, 0x00, 0x01, 0, 0, 0xE8, 0xF1, 0x0F, 0, 0 };
    CHECK(callersOf(code, 0x2000, 0x3000) == std::vector<std::uint64_t>({ 0x2000, 0x200A }));
}
TEST("a cut-off call is ignored") { CHECK(callTargets({ 0x90, 0xE8, 1, 2 }, 0x10).empty()); }
TEST("padding only") { CHECK(callTargets({ 0xCC, 0xCC, 0x90 }, 0x10).empty()); }

